import{_ as n,l as o,o as e,c as l,v as t,p as s,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"策略生命周期","description":"","frontmatter":{"title":"策略生命周期","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/strategy-lifecycle.md","filePath":"quant/strategy-lifecycle.md","lastUpdated":1789023840000}'),E={name:"quant/strategy-lifecycle.md"};function p(u,a,f,m,_,q){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="策略生命周期" tabindex="-1">策略生命周期 <a class="header-anchor" href="#策略生命周期" aria-label="Permalink to &quot;策略生命周期&quot;">​</a></h1><div class="epigraph"><p>异象在样本内被发现、在论文与产品里被传播、在资金涌入后衰减；发表后的衰减不是市场变有效的修辞，而是可测量的拥挤与成本上升。</p><footer>—— McLean and Pontiff, Does Academic Research Destroy Stock Return Predictability?, Journal of Finance, 2016</footer></div><p><a href="/quant/thematic-narrative">上一课</a>把主题收进风格资金。策略地图到此走完多空、宏观、RV、ARP 与叙事。生命周期的缺口是<strong>所有这些腿都会老化</strong>。主干 <a href="/quant/multiple-testing-factors">多重检验</a>、<a href="/quant/factor-crowding">因子拥挤</a>、<a href="/quant/net-edge">净边缘</a>、<a href="/quant/strategy-capacity">策略容量</a> 已写零件。本课收口策略族：发现–产品化–拥挤–衰减–退役，后面业绩单元不再把样本内夏普当永续。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>McLean–Pontiff 比较论文样本内、发表后、样本外：可预测性平均下降，成本高的异象降得更多。Harvey–Liu–Zhu 说明发现阶段已经有选择偏差。问题是运营：何时把研究仓转成产品仓，何时降杠杆，何时停。不能等全样本 t 值掉到 1 再议——那时容量已经满了。Schwert 对异象「被发现后变弱」的观察与此同方向。</p><p>与择时：生命周期减仓是对<strong>策略自身拥挤</strong>的反应，不是对因子估值的逆向择时。两者可以同时发生，报告要分开。</p><h3 id="衰减不是证明当初是假的" tabindex="-1">衰减不是证明当初是假的 <a class="header-anchor" href="#衰减不是证明当初是假的" aria-label="Permalink to &quot;衰减不是证明当初是假的&quot;">​</a></h3><p>选择偏差解释一部分发表后下降；真实拥挤解释另一部分。把所有衰减都说成 p-hacking，会错过风控；把所有衰减都说成拥挤，会给假策略续命。应用发表前后、成本分层、持仓重叠一起看。</p><p><span class="marginnote">产品化本身加速衰减：透明规则、因子 ETF、风险模型里的风格因子，都在把信号变成公共品。ARP 课里「规则化便于复制」在这里变成成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>档案：预注册、试验次数、扣费后样本外。监控：IC 衰减、换手成本、拥挤代理、相关升。治理：预先写停损与退役规则（容量、IR 下限、拥挤上限）。新产品对照：相对已有腿的增量 IR，而不是孤立夏普。过 <a href="/quant/deflated-sharpe">放气夏普</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现把噪声标成信号；资本把信号标成拥挤；冲击与费用把拥挤标成零边缘。Grossman–Stiglitz 式的信息补偿在边际上被复制成本吃掉——此处只引用，不重推均衡。地图上每类策略的时钟不同：并购套利随 deal 流，短波动随卖方拥挤，日历效应随发表次数。</p>',13)),(e(),s(h,null,{default:r(()=>[c(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Disc%5B%22%E5%8F%91%E7%8E%B0%E4%B8%8E%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%22%5D%20--%3E%20Prod%5B%22%E4%BA%A7%E5%93%81%E5%8C%96%20%E8%A7%84%E5%88%99%E5%85%AC%E5%BC%80%22%5D%0A%20%20Prod%20--%3E%20Crowd%5B%22%E8%B5%84%E9%87%91%E4%B8%8E%E6%9D%A0%E6%9D%86%22%5D%0A%20%20Crowd%20--%3E%20Decay%5B%22%E6%88%90%E6%9C%AC%E5%90%8E%E8%BE%B9%E7%BC%98%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Decay%20--%3E%20Ret%5B%22%E9%80%80%E5%BD%B9%E6%88%96%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定具体退役数值。法律与营销不能承诺「历史夏普会重复」。下一单元改问：即便策略还在，费用与业绩会计会吃掉多少。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>策略有发现–拥挤–衰减的生命周期，样本内夏普不是产品。</li><li>发表后衰减来自选择偏差与真实拥挤，要一起度量。</li><li>退役规则预先写，增量 IR 相对已有腿。</li><li>出处：McLean and Pontiff, <em>JF</em>, 2016；Harvey, Liu and Zhu, <em>RFS</em>, 2016。</li></ul>',4))])}const D=n(E,[["render",p]]);export{B as __pageData,D as default};
